class Solution { vector<int> tree;vector<bool> lazy;void build(int node,int left,int right,vector<int>& nums){if(left==right){tree[node]=nums[left];return;}int middle=(left+right)/2;build(node*2,left,middle,nums);build(node*2+1,middle+1,right,nums);tree[node]=tree[node*2]+tree[node*2+1];}void flip(int node,int left,int right){tree[node]=right-left+1-tree[node];lazy[node]=!lazy[node];}void push(int node,int left,int right){if(!lazy[node]||left==right)return;int middle=(left+right)/2;flip(node*2,left,middle);flip(node*2+1,middle+1,right);lazy[node]=false;}void update(int node,int left,int right,int queryLeft,int queryRight){if(queryLeft<=left&&right<=queryRight){flip(node,left,right);return;}push(node,left,right);int middle=(left+right)/2;if(queryLeft<=middle)update(node*2,left,middle,queryLeft,queryRight);if(queryRight>middle)update(node*2+1,middle+1,right,queryLeft,queryRight);tree[node]=tree[node*2]+tree[node*2+1];}public:vector<long long> handleQuery(vector<int>& nums1,vector<int>& nums2,vector<vector<int>>& queries){int n=nums1.size();tree.resize(4*n);lazy.resize(4*n);build(1,0,n-1,nums1);long long sum=accumulate(nums2.begin(),nums2.end(),0LL);vector<long long> reports;for(auto& query:queries){if(query[0]==1)update(1,0,n-1,query[1],query[2]);else if(query[0]==2)sum+=1LL*query[1]*tree[1];else reports.push_back(sum);}return reports;} };
